// Screen 19 of 29. Generated by Google Stitch, source folder 19-skip_room.
// Rebuilt 3 August 2026: the generated version was inert. Its radios had
// `groupValue: null` and `onChanged: (v){}`, the text field had no controller,
// and Confirm had an empty handler. Nothing could be selected or submitted.
//
// A SKIP IS EVIDENCE.
// It is recorded against the booking and counts against whoever skipped it if
// there is ever a claim. So the reason is required, and the guest is told
// plainly that it is shared. Nobody is ever trapped in the capture flow, but
// nobody skips silently either.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import '../theme/stay_colors.dart';

/// Returns the chosen reason through `Navigator.pop`, or null if dismissed.
class SkipRoomSheet extends StatefulWidget {
  const SkipRoomSheet({super.key, this.room});

  /// The room being skipped, for example 'Bedroom 1'. Shown in the title so
  /// the guest can see they are skipping the one they meant to.
  final String? room;

  @override
  State<SkipRoomSheet> createState() => _SkipRoomSheetState();
}

class _SkipRoomSheetState extends State<SkipRoomSheet> {
  static const _reasons = <String>[
    'The room is locked',
    'Someone is asleep',
    'I cannot access it',
    'Other',
  ];

  String? _selected;
  final _otherCtrl = TextEditingController();

  @override
  void initState() {
    super.initState();
    // Rebuild the Confirm button as the free text changes, so it enables the
    // moment there is something to submit.
    _otherCtrl.addListener(_onOtherChanged);
  }

  void _onOtherChanged() => setState(() {});

  @override
  void dispose() {
    _otherCtrl.removeListener(_onOtherChanged);
    _otherCtrl.dispose();
    super.dispose();
  }

  bool get _isOther => _selected == 'Other';

  /// Confirm stays disabled until there is a real reason. Choosing Other and
  /// leaving the box empty is not a reason.
  bool get _canConfirm =>
      _selected != null && (!_isOther || _otherCtrl.text.trim().isNotEmpty);

  String get _reasonToRecord =>
      _isOther ? _otherCtrl.text.trim() : (_selected ?? '');

  void _confirm() {
    if (!_canConfirm) return;
    Navigator.of(context).pop(_reasonToRecord);
  }

  @override
  Widget build(BuildContext context) {
    final title = widget.room == null
        ? 'Why are you skipping this room?'
        : 'Why are you skipping ${widget.room}?';

    return Padding(
      // Lift above the keyboard when the free text box is open.
      padding: EdgeInsets.only(
        bottom: MediaQuery.viewInsetsOf(context).bottom,
      ),
      child: Container(
        padding: const EdgeInsets.all(24),
        decoration: const BoxDecoration(
          color: GoOutsColors.cardSurface,
          borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
        ),
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 40,
                  height: 4,
                  margin: const EdgeInsets.only(bottom: 20),
                  decoration: BoxDecoration(
                    color: GoOutsColors.outlineVariant,
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
              ),
              Text(
                title,
                style: GoogleFonts.inter(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: GoOutsColors.deepNavy,
                ),
              ),
              const SizedBox(height: 12),

              // RadioGroup, not per-Radio groupValue and onChanged. Those were
              // deprecated after Flutter 3.32.
              RadioGroup<String>(
                groupValue: _selected,
                onChanged: (v) => setState(() => _selected = v),
                child: Column(
                  children: [
                    for (final r in _reasons)
                      RadioListTile<String>(
                        value: r,
                        contentPadding: EdgeInsets.zero,
                        activeColor: GoOutsColors.primaryBlue,
                        title: Text(
                          r,
                          style: GoogleFonts.inter(
                            fontSize: 16,
                            color: GoOutsColors.deepNavy,
                          ),
                        ),
                      ),
                  ],
                ),
              ),

              if (_isOther)
                Padding(
                  padding: const EdgeInsets.only(left: 16, top: 4),
                  child: TextField(
                    controller: _otherCtrl,
                    autofocus: true,
                    maxLength: 200,
                    textCapitalization: TextCapitalization.sentences,
                    decoration: InputDecoration(
                      hintText: 'Tell us why',
                      counterText: '',
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(8),
                      ),
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 12, vertical: 10),
                    ),
                  ),
                ),

              const SizedBox(height: 20),
              Text(
                'Skipping is recorded and is shared with your host, so the '
                'record is fair to both of you. You will not be stopped from '
                'finishing.',
                style: GoogleFonts.inter(
                  fontSize: 13,
                  height: 1.5,
                  color: GoOutsColors.bodyText,
                ),
              ),
              const SizedBox(height: 24),

              // Muted, not brand blue. Skipping is allowed, not encouraged.
              ElevatedButton(
                onPressed: _canConfirm ? _confirm : null,
                style: ElevatedButton.styleFrom(
                  backgroundColor: GoOutsColors.dividerGray,
                  foregroundColor: GoOutsColors.deepNavy,
                  disabledBackgroundColor: GoOutsColors.dividerGray,
                  disabledForegroundColor: GoOutsColors.outlineVariant,
                  minimumSize: const Size(double.infinity, 56),
                  elevation: 0,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
                child: Text(
                  'Confirm skip',
                  style: GoogleFonts.inter(fontWeight: FontWeight.bold),
                ),
              ),
              const SizedBox(height: 8),
              Center(
                child: TextButton(
                  onPressed: () => Navigator.of(context).pop(),
                  child: Text(
                    'Photograph it instead',
                    style: GoogleFonts.inter(
                      fontWeight: FontWeight.w600,
                      color: GoOutsColors.primaryBlue,
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
